import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

// #12: the customer's discount applies once, then the bulk discount once.
test('customer discount applies once below 10 lines', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900); // 1000 * 0.9
});

test('customer discount, then the 5% bulk discount once, from 10 lines', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10000 * 0.9 * 0.95
});

// A total with a customer discount drops the fraction below one yen.
test('discounted total drops the fraction below one yen', () => {
  assert.equal(total([{ price: 995, qty: 1 }], 0.15), 845); // 995 * 0.85 = 845.75
});

test('discounted bulk total drops the fraction below one yen', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 12, qty: 1 }));
  assert.equal(total(lines, 0.1), 102); // 120 * 0.9 * 0.95 = 102.6
});

test('an exact discounted amount does not lose a yen to float noise', () => {
  assert.equal(total([{ price: 2150, qty: 1 }], 0.06), 2021); // 2150 * 0.94 = 2021 exactly
  assert.equal(total([{ price: 1000, qty: 1 }], 0.9), 100); // 1000 * 0.1 = 100 exactly
});
