// Compare candidate floor implementations against exact rational arithmetic.
// Exact: subtotal * (D - d) * (bulk ? 95 : 100) / (D * 100), D = 10^decimals.
const naive = (x) => Math.floor(x);
const snap6 = (x) => Math.floor(Math.round(x * 1e6) / 1e6);
const res = {};
for (const decimals of [2, 3, 4]) {
  const D = 10 ** decimals;
  const step = decimals === 2 ? 1 : decimals === 3 ? 7 : 61;
  let n = 0, badNaive = 0, badSnap = 0, ex = null;
  for (let di = 1; di < D; di += step) {
    const d = di / D;
    for (const bulk of [0, 0.05]) {
      for (let s = 1; s <= 20000; s += 1) {
        const exact = Number((BigInt(s) * BigInt(D - di) * BigInt(bulk ? 95 : 100)) / BigInt(D * 100));
        const x = s * (1 - d) * (1 - bulk);
        n++;
        if (naive(x) !== exact) { badNaive++; ex ??= { s, d, bulk, x, exact }; }
        if (snap6(x) !== exact) badSnap++;
      }
    }
  }
  res[decimals] = { n, badNaive, badSnap, firstNaiveMiss: ex };
}
console.log(JSON.stringify(res, null, 1));
// Big amounts
let badBig = 0, nb = 0;
for (const s of [1e6, 12345678, 99999999, 1e9, 2147483647]) for (let di = 1; di < 100; di++) for (const bulk of [0, 0.05]) {
  const exact = Number((BigInt(s) * BigInt(100 - di) * BigInt(bulk ? 95 : 100)) / 10000n);
  nb++; if (snap6(s * (1 - di / 100) * (1 - bulk)) !== exact) badBig++;
}
console.log({ nb, badBig });
// d = 0 half-yen cases with Math.round (existing behaviour): any subtotal where float noise breaks half-up?
let half = 0, halfBad = 0;
for (let s = 10; s <= 2_000_000; s += 20) { half++; if (Math.round(s * 1 * 0.95) !== (s * 95 + 50) / 100) halfBad++; }
console.log({ half, halfBad });

