src/cart.js.text:
// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount.
// The customer's discount applies once, then the bulk discount once (#12).
//
// Rounding: with a customer discount, the fraction below one yen is dropped.
// Without one (rate 0) half a yen is rounded up, as before — wholesale invoices
// (#7) are billed from this total and must match the printed price list.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const payable = 1 - discount; // share of the price the customer pays
  const discounted = subtotal * payable * (1 - bulk);
  if (payable === 1) return Math.round(discounted); // no customer discount: as before
  return floorYen(discounted);
}

// Floor to whole yen. Float noise can leave an exact amount a hair below the
// integer (2150 * (1 - 0.06) is 2020.9999999999998), so snap to 6 decimals first.
// Good for rates with up to 4 decimals and subtotals below a billion yen.
function floorYen(amount) {
  return Math.floor(Math.round(amount * 1e6) / 1e6);
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

src/invoice.js.text:
import { total } from './cart.js';

// Invoices for wholesale orders (#7). The amount due is the cart total as it is:
// wholesale customers order from a printed price list that follows the same rules —
// list price below 10 lines, 5% off from 10 lines, half a yen rounded up.
export function invoice(customer, items) {
  return { customer, due: total(items) };
}

